type Produk = { nama: string; harga: number };
function isProduk(x: unknown): x is Produk {
  return (
    typeof x === "object" && x !== null &&
    "nama" in x && typeof x.nama === "string" &&
    "harga" in x && typeof x.harga === "number"
  );
}
const dariServer: unknown[] = [
  { nama: "Kopi", harga: 18000 },
  { nama: "Teh" },
  "rusak",
  { nama: "Roti", harga: 15000 },
];
const valid = dariServer.filter(isProduk);
console.log(valid.map((p) => p.nama));
console.log(valid.reduce((a, p) => a + p.harga, 0));

