cards.solution:
function isEmail(x: unknown): x is string {
  if (typeof x !== "string") return false;
  const at = x.indexOf("@");
  return at > 0 && x.indexOf(".", at) > at + 1;
}
const data: unknown[] = ["rina@toko.id", 42, "salah", "budi@mail.com", null];
console.log(data.filter(isEmail).join(", "));
